export function graphql(source: "mutation ReportPlaybackFormatFailure($input: ReportPlaybackFormatFailureInput!) {\n  reportPlaybackFormatFailure(input: $input) {\n    playbackSession {\n      ...PlaybackSessionFields\n    }\n    userErrors {\n      __typename\n      ... on MutationError {\n        message\n      }\n    }\n  }\n}"): (typeof documents)["mutation ReportPlaybackFormatFailure($input: ReportPlaybackFormatFailureInput!) {\n  reportPlaybackFormatFailure(input: $input) {\n    playbackSession {\n      ...PlaybackSessionFields\n    }\n    userErrors {\n      __typename\n      ... on MutationError {\n        message\n      }\n    }\n  }\n}"];

export function graphql(source: string) {
  return (documents as any)[source] ?? {};
}

export type DocumentType<TDocumentNode extends DocumentNode<any, any>> = TDocumentNode extends DocumentNode<  infer TType,  any>  ? TType  : never;